def dsa_ext_pv_of_ppg_external_debt_to_gdp_ratio(*, dsa_ext_nominal_gdp_million_of_us_dollars: data.Series[float | str | None], dsa_ext_pv_ppg_stress: data.Series[float | str | None], ext_debt_total_pv_of_debt: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `dsa_ext_pv_of_ppg_external_debt_to_gdp_ratio` using authored coordinate identities."""
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario in ('A1', 'B1', 'B3', 'B4', 'B5', 'B6_mkt', 'B6_nonmkt', 'C3') and time_period == 2024:
            return as_measure(dsa_ext_pv_of_ppg_external_debt_to_gdp_ratio['Baseline', time_period])
        elif scenario == 'A1' and time_period >= 2025:
            return as_measure((0 if xl_bool(xl_lt(xl_mul(xl_div(dsa_ext_pv_ppg_stress[scenario, time_period], dsa_ext_nominal_gdp_million_of_us_dollars[scenario, time_period]), 100), 0)) else xl_mul(xl_div(dsa_ext_pv_ppg_stress[scenario, time_period], dsa_ext_nominal_gdp_million_of_us_dollars[scenario, time_period]), 100)))
        elif scenario == 'Baseline':
            return as_measure((0 if xl_bool(xl_lt(xl_mul(xl_div(ext_debt_total_pv_of_debt[time_period], dsa_ext_nominal_gdp_million_of_us_dollars[scenario, time_period]), 100), 0)) else xl_mul(xl_div(ext_debt_total_pv_of_debt[time_period], dsa_ext_nominal_gdp_million_of_us_dollars[scenario, time_period]), 100)))
        return as_measure(xl_mul(xl_div(dsa_ext_pv_ppg_stress[scenario, time_period], dsa_ext_nominal_gdp_million_of_us_dollars[scenario, time_period]), 100))

    dsa_ext_pv_of_ppg_external_debt_to_gdp_ratio = CoordinateReader('dsa_ext_pv_of_ppg_external_debt_to_gdp_ratio', data.DSA_EXT_PV_OF_PPG_EXTERNAL_DEBT_TO_GDP_RATIO.required, formula)
    return data.DSA_EXT_PV_OF_PPG_EXTERNAL_DEBT_TO_GDP_RATIO.collect((coord, dsa_ext_pv_of_ppg_external_debt_to_gdp_ratio[coord]) for coord in data.DSA_EXT_PV_OF_PPG_EXTERNAL_DEBT_TO_GDP_RATIO.required)

