@dataclass(frozen=True, slots=True)
class ScanDsaExtDepreciationOfNcDepreciationResult:
    """Complete named results of one recurrence group evaluation."""
    dsa_ext_depreciation_of_nc_depreciation: data.Series[float | str | None]
    dsa_ext_standard_test_fx_depreciation: data.Series[float | str | None]
    in6opt_standard_size_of_fx_depreciation_shock: data.Series[float | str | None]
    in6opt_standard_b6_combination_size_of_fx_depreciation_shock: data.Series[float | str | None]

def scan_dsa_ext_depreciation_of_nc_depreciation(*, lookup_ida_terms_new: str, input6_standard_size_threshold_mode: str, in6opt_standard_nominal_depreciation_close_real_overvaluation: data.Series[float | str | None], macro_debt_depreciation_of_nc_depreciation: data.Series[float | str | None]) -> ScanDsaExtDepreciationOfNcDepreciationResult:
    """Evaluate the recurrence group `dsa_ext_depreciation_of_nc_depreciation`, `dsa_ext_standard_test_fx_depreciation`, `in6opt_standard_size_of_fx_depreciation_shock`, `in6opt_standard_b6_combination_size_of_fx_depreciation_shock` and publish complete tensors."""
    def dsa_ext_depreciation_of_nc_depreciation_formula(scenario: str, time_period: int) -> float | str | None:
        if scenario in ('B5', 'B6_mkt', 'B6_nonmkt') and time_period == 2025:
            return as_measure(dsa_ext_standard_test_fx_depreciation[scenario])
        elif scenario == 'Baseline':
            return as_measure((macro_debt_depreciation_of_nc_depreciation[time_period] if xl_bool(xl_isnumber(lambda: macro_debt_depreciation_of_nc_depreciation[time_period])) else '...'))
        return as_measure(dsa_ext_depreciation_of_nc_depreciation['Baseline', time_period])

    dsa_ext_depreciation_of_nc_depreciation = CoordinateReader('dsa_ext_depreciation_of_nc_depreciation', data.DSA_EXT_DEPRECIATION_OF_NC_DEPRECIATION.required, dsa_ext_depreciation_of_nc_depreciation_formula)
    def dsa_ext_standard_test_fx_depreciation_formula(scenario: str) -> float | str | None:
        if scenario == 'B5':
            return as_measure((in6opt_standard_size_of_fx_depreciation_shock['User defined'] if xl_bool(xl_eq(input6_standard_size_threshold_mode, lookup_ida_terms_new)) else in6opt_standard_size_of_fx_depreciation_shock['Default']))
        return as_measure((in6opt_standard_b6_combination_size_of_fx_depreciation_shock['User defined'] if xl_bool(xl_eq(input6_standard_size_threshold_mode, lookup_ida_terms_new)) else in6opt_standard_b6_combination_size_of_fx_depreciation_shock['Default']))

    dsa_ext_standard_test_fx_depreciation = CoordinateReader('dsa_ext_standard_test_fx_depreciation', data.DSA_EXT_STANDARD_TEST_FX_DEPRECIATION.required, dsa_ext_standard_test_fx_depreciation_formula)
    def in6opt_standard_size_of_fx_depreciation_shock_formula(variant: str) -> float | str | None:
        if variant == 'Default':
            return as_measure((xl_max(30, in6opt_standard_nominal_depreciation_close_real_overvaluation[variant]) if xl_bool(xl_eq(input6_standard_size_threshold_mode, 'New')) else xl_add(30, dsa_ext_depreciation_of_nc_depreciation['Baseline', 2025])))
        return as_measure(xl_max(30, in6opt_standard_nominal_depreciation_close_real_overvaluation[variant]))

    in6opt_standard_size_of_fx_depreciation_shock = CoordinateReader('in6opt_standard_size_of_fx_depreciation_shock', data.IN6OPT_STANDARD_SIZE_OF_FX_DEPRECIATION_SHOCK.required, in6opt_standard_size_of_fx_depreciation_shock_formula)
    def in6opt_standard_b6_combination_size_of_fx_depreciation_shock_formula(variant: str) -> float | str | None:
        if variant == 'Default':
            return as_measure((xl_div(in6opt_standard_size_of_fx_depreciation_shock[variant], 2) if xl_bool(xl_eq(input6_standard_size_threshold_mode, 'New')) else 0))
        return as_measure(xl_div(in6opt_standard_size_of_fx_depreciation_shock[variant], 2))

    in6opt_standard_b6_combination_size_of_fx_depreciation_shock = CoordinateReader('in6opt_standard_b6_combination_size_of_fx_depreciation_shock', data.IN6OPT_STANDARD_B6_COMBINATION_SIZE_OF_FX_DEPRECIATION_SHOCK.required, in6opt_standard_b6_combination_size_of_fx_depreciation_shock_formula)
    return ScanDsaExtDepreciationOfNcDepreciationResult(
        dsa_ext_depreciation_of_nc_depreciation=data.DSA_EXT_DEPRECIATION_OF_NC_DEPRECIATION.collect((coord, dsa_ext_depreciation_of_nc_depreciation[coord]) for coord in data.DSA_EXT_DEPRECIATION_OF_NC_DEPRECIATION.required),
        dsa_ext_standard_test_fx_depreciation=data.DSA_EXT_STANDARD_TEST_FX_DEPRECIATION.collect((coord, dsa_ext_standard_test_fx_depreciation[coord]) for coord in data.DSA_EXT_STANDARD_TEST_FX_DEPRECIATION.required),
        in6opt_standard_size_of_fx_depreciation_shock=data.IN6OPT_STANDARD_SIZE_OF_FX_DEPRECIATION_SHOCK.collect((coord, in6opt_standard_size_of_fx_depreciation_shock[coord]) for coord in data.IN6OPT_STANDARD_SIZE_OF_FX_DEPRECIATION_SHOCK.required),
        in6opt_standard_b6_combination_size_of_fx_depreciation_shock=data.IN6OPT_STANDARD_B6_COMBINATION_SIZE_OF_FX_DEPRECIATION_SHOCK.collect((coord, in6opt_standard_b6_combination_size_of_fx_depreciation_shock[coord]) for coord in data.IN6OPT_STANDARD_B6_COMBINATION_SIZE_OF_FX_DEPRECIATION_SHOCK.required),
    )

