@publish(data.DSA_EXT_REVENUE_GDP_STRESS_STRESS.schema, cells=data.DSA_EXT_REVENUE_GDP_STRESS_STRESS.cells)
def dsa_ext_revenue_gdp_stress_stress(*, dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp: data.Series[float | str | None], leftover_us_gdp_deflator: data.Series[float | str | None], c3_commodity_ext_ii_key_macroeconomic_assumptions: int | str) -> data.Series[float | str | None]:
    """Compute `dsa_ext_revenue_gdp_stress_stress` using authored coordinate identities."""
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2028:
            return as_measure(xl_sub(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], xl_div(xl_mul(leftover_us_gdp_deflator[scenario], xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 3)), xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 2))))
        elif time_period == 2029:
            return as_measure(xl_sub(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], xl_div(xl_mul(leftover_us_gdp_deflator[scenario], xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 4)), xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 2))))
        elif time_period == 2030:
            return as_measure(xl_sub(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], xl_div(xl_mul(leftover_us_gdp_deflator[scenario], xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 5)), xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 2))))
        return as_measure(xl_sub(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], leftover_us_gdp_deflator[scenario]))

    return data.DSA_EXT_REVENUE_GDP_STRESS_STRESS.collect(evaluate(formula, data.DSA_EXT_REVENUE_GDP_STRESS_STRESS.required))

