@dataclass(frozen=True, slots=True)
class ScanDsaPubPublicSectorDebt1Result:
    """Complete named results of one recurrence group evaluation."""
    dsa_pub_public_sector_debt_1: data.Series[float | str | None]
    dsa_pub_change_in_public_sector_debt: data.Series[float | str | None]
    dsa_pub_identified_debt_creating_flows: data.Series[float | str | None]
    dsa_pub_automatic_debt_dynamics: data.Series[float | str | None]
    dsa_pub_contribution_from_interest_rate_growth_differential: data.Series[float | str | None]
    dsa_pub_of_which_contribution_from_average_real_interest_rate: data.Series[float | str | None]
    dsa_pub_of_which_contribution_from_real_gdp_growth: data.Series[float | str | None]
    dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent: data.Series[float | str | None]
    dsa_pub_average_real_interest_rate_in_percent: data.Series[float | str | None]
    dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent: data.Series[float | str | None]
    dsa_pub_nominal_debt: data.Series[float | str | None]
    dsa_pub_total_public_domestic_debt: data.Series[float | str | None]

def scan_dsa_pub_public_sector_debt_1(*, dsa_pub_of_which_external_debt: data.Series[float | str | None], dsa_pub_primary_deficit: data.Series[float | str | None], dsa_pub_contribution_from_real_exchange_rate_depreciation: data.Series[float | str | None], dsa_pub_denominator_1_g: data.Series[float | str | None], dsa_pub_other_identified_debt_creating_flows: data.Series[float | str | None], dsa_pub_residual: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_real_gdp_growth_in_percent: data.Series[float | str | None], dsa_pub_average_real_interest_rate_on_external_debt_in_percent: data.Series[float | str | None], dsa_pub_inflation_rate_gdp_deflator_in_percent: data.Series[float | str | None], dsa_pub_total_public_external_debt: data.Series[float | str | None], dsa_pub_domestic_debt: data.Series[float | str | None], macro_debt_gdp_current_prices_u_s_dollars: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], macro_debt_total_public_debt_outstanding_year_end: data.Series[float | str | None], pv_resfin_pub_assumptions_average_interest_rate_on_domestic_debt: data.Series[float | str | None]) -> ScanDsaPubPublicSectorDebt1Result:
    """Evaluate the recurrence group `dsa_pub_public_sector_debt_1`, `dsa_pub_change_in_public_sector_debt`, `dsa_pub_identified_debt_creating_flows`, `dsa_pub_automatic_debt_dynamics`, `dsa_pub_contribution_from_interest_rate_growth_differential`, `dsa_pub_of_which_contribution_from_average_real_interest_rate`, `dsa_pub_of_which_contribution_from_real_gdp_growth`, `dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent`, `dsa_pub_average_real_interest_rate_in_percent`, `dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent`, `dsa_pub_nominal_debt`, `dsa_pub_total_public_domestic_debt` and publish complete tensors."""
    def dsa_pub_public_sector_debt_1_formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure((xl_div(xl_mul(100, macro_debt_total_public_debt_outstanding_year_end[time_period]), xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])) if xl_bool(xl_isnumber(lambda: xl_div(macro_debt_total_public_debt_outstanding_year_end[time_period], xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])))) else '.'))
        return as_measure(xl_add(dsa_pub_public_sector_debt_1[scenario, time_period - 1], dsa_pub_change_in_public_sector_debt[scenario, time_period]))

    dsa_pub_public_sector_debt_1 = CoordinateReader('dsa_pub_public_sector_debt_1', data.DSA_PUB_PUBLIC_SECTOR_DEBT_1.required, dsa_pub_public_sector_debt_1_formula)
    def dsa_pub_change_in_public_sector_debt_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(dsa_pub_identified_debt_creating_flows[scenario, time_period], dsa_pub_residual[scenario, time_period]))

    dsa_pub_change_in_public_sector_debt = CoordinateReader('dsa_pub_change_in_public_sector_debt', data.DSA_PUB_CHANGE_IN_PUBLIC_SECTOR_DEBT.required, dsa_pub_change_in_public_sector_debt_formula)
    def dsa_pub_identified_debt_creating_flows_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(dsa_pub_primary_deficit[scenario, time_period], dsa_pub_automatic_debt_dynamics[scenario, time_period]), dsa_pub_other_identified_debt_creating_flows[scenario, time_period]))

    dsa_pub_identified_debt_creating_flows = CoordinateReader('dsa_pub_identified_debt_creating_flows', data.DSA_PUB_IDENTIFIED_DEBT_CREATING_FLOWS.required, dsa_pub_identified_debt_creating_flows_formula)
    def dsa_pub_automatic_debt_dynamics_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(dsa_pub_contribution_from_interest_rate_growth_differential[scenario, time_period], dsa_pub_contribution_from_real_exchange_rate_depreciation[scenario, time_period]))

    dsa_pub_automatic_debt_dynamics = CoordinateReader('dsa_pub_automatic_debt_dynamics', data.DSA_PUB_AUTOMATIC_DEBT_DYNAMICS.required, dsa_pub_automatic_debt_dynamics_formula)
    def dsa_pub_contribution_from_interest_rate_growth_differential_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(dsa_pub_of_which_contribution_from_average_real_interest_rate[scenario, time_period], dsa_pub_of_which_contribution_from_real_gdp_growth[scenario, time_period]))

    dsa_pub_contribution_from_interest_rate_growth_differential = CoordinateReader('dsa_pub_contribution_from_interest_rate_growth_differential', data.DSA_PUB_CONTRIBUTION_FROM_INTEREST_RATE_GROWTH_DIFFERENTIAL.required, dsa_pub_contribution_from_interest_rate_growth_differential_formula)
    def dsa_pub_of_which_contribution_from_average_real_interest_rate_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(xl_div(dsa_pub_average_real_interest_rate_in_percent[scenario, time_period], 100), dsa_pub_public_sector_debt_1[scenario, time_period - 1]), dsa_pub_denominator_1_g[scenario, time_period]))

    dsa_pub_of_which_contribution_from_average_real_interest_rate = CoordinateReader('dsa_pub_of_which_contribution_from_average_real_interest_rate', data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_AVERAGE_REAL_INTEREST_RATE.required, dsa_pub_of_which_contribution_from_average_real_interest_rate_formula)
    def dsa_pub_of_which_contribution_from_real_gdp_growth_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_neg(xl_div(dsa_pub_real_gdp_growth_in_percent[scenario, time_period], 100)), xl_div(dsa_pub_public_sector_debt_1[scenario, time_period - 1], dsa_pub_denominator_1_g[scenario, time_period])))

    dsa_pub_of_which_contribution_from_real_gdp_growth = CoordinateReader('dsa_pub_of_which_contribution_from_real_gdp_growth', data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_REAL_GDP_GROWTH.required, dsa_pub_of_which_contribution_from_real_gdp_growth_formula)
    def dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure((xl_mul(pv_resfin_pub_assumptions_average_interest_rate_on_domestic_debt[time_period], 100) if xl_bool(xl_eq(dsa_pub_total_public_domestic_debt[scenario, time_period - 1], 0)) else xl_mul(xl_div(dsa_pub_domestic_debt[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period - 1]), 100)))

    dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent = CoordinateReader('dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent', data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT.required, dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent_formula)
    def dsa_pub_average_real_interest_rate_in_percent_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_mul(xl_div(dsa_pub_of_which_external_debt[scenario, time_period - 1], dsa_pub_public_sector_debt_1[scenario, time_period - 1]), dsa_pub_average_real_interest_rate_on_external_debt_in_percent[scenario, time_period]), xl_mul(xl_sub(1, xl_div(dsa_pub_of_which_external_debt[scenario, time_period - 1], dsa_pub_public_sector_debt_1[scenario, time_period - 1])), dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent[scenario, time_period])))

    dsa_pub_average_real_interest_rate_in_percent = CoordinateReader('dsa_pub_average_real_interest_rate_in_percent', data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_IN_PERCENT.required, dsa_pub_average_real_interest_rate_in_percent_formula)
    def dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_sub(dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent[scenario, time_period], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, time_period]), xl_add(1, xl_div(dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))))

    dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent = CoordinateReader('dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent', data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT.required, dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent_formula)
    def dsa_pub_nominal_debt_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(dsa_pub_public_sector_debt_1[scenario, time_period], 100), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    dsa_pub_nominal_debt = CoordinateReader('dsa_pub_nominal_debt', data.DSA_PUB_NOMINAL_DEBT.required, dsa_pub_nominal_debt_formula)
    def dsa_pub_total_public_domestic_debt_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_sub(dsa_pub_nominal_debt[scenario, time_period], dsa_pub_total_public_external_debt[scenario, time_period]))

    dsa_pub_total_public_domestic_debt = CoordinateReader('dsa_pub_total_public_domestic_debt', data.DSA_PUB_TOTAL_PUBLIC_DOMESTIC_DEBT.required, dsa_pub_total_public_domestic_debt_formula)
    return ScanDsaPubPublicSectorDebt1Result(
        dsa_pub_public_sector_debt_1=data.DSA_PUB_PUBLIC_SECTOR_DEBT_1.collect((coord, dsa_pub_public_sector_debt_1[coord]) for coord in data.DSA_PUB_PUBLIC_SECTOR_DEBT_1.required),
        dsa_pub_change_in_public_sector_debt=data.DSA_PUB_CHANGE_IN_PUBLIC_SECTOR_DEBT.collect((coord, dsa_pub_change_in_public_sector_debt[coord]) for coord in data.DSA_PUB_CHANGE_IN_PUBLIC_SECTOR_DEBT.required),
        dsa_pub_identified_debt_creating_flows=data.DSA_PUB_IDENTIFIED_DEBT_CREATING_FLOWS.collect((coord, dsa_pub_identified_debt_creating_flows[coord]) for coord in data.DSA_PUB_IDENTIFIED_DEBT_CREATING_FLOWS.required),
        dsa_pub_automatic_debt_dynamics=data.DSA_PUB_AUTOMATIC_DEBT_DYNAMICS.collect((coord, dsa_pub_automatic_debt_dynamics[coord]) for coord in data.DSA_PUB_AUTOMATIC_DEBT_DYNAMICS.required),
        dsa_pub_contribution_from_interest_rate_growth_differential=data.DSA_PUB_CONTRIBUTION_FROM_INTEREST_RATE_GROWTH_DIFFERENTIAL.collect((coord, dsa_pub_contribution_from_interest_rate_growth_differential[coord]) for coord in data.DSA_PUB_CONTRIBUTION_FROM_INTEREST_RATE_GROWTH_DIFFERENTIAL.required),
        dsa_pub_of_which_contribution_from_average_real_interest_rate=data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_AVERAGE_REAL_INTEREST_RATE.collect((coord, dsa_pub_of_which_contribution_from_average_real_interest_rate[coord]) for coord in data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_AVERAGE_REAL_INTEREST_RATE.required),
        dsa_pub_of_which_contribution_from_real_gdp_growth=data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_REAL_GDP_GROWTH.collect((coord, dsa_pub_of_which_contribution_from_real_gdp_growth[coord]) for coord in data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_REAL_GDP_GROWTH.required),
        dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent=data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT.collect((coord, dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent[coord]) for coord in data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT.required),
        dsa_pub_average_real_interest_rate_in_percent=data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_IN_PERCENT.collect((coord, dsa_pub_average_real_interest_rate_in_percent[coord]) for coord in data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_IN_PERCENT.required),
        dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent=data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT.collect((coord, dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent[coord]) for coord in data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT.required),
        dsa_pub_nominal_debt=data.DSA_PUB_NOMINAL_DEBT.collect((coord, dsa_pub_nominal_debt[coord]) for coord in data.DSA_PUB_NOMINAL_DEBT.required),
        dsa_pub_total_public_domestic_debt=data.DSA_PUB_TOTAL_PUBLIC_DOMESTIC_DEBT.collect((coord, dsa_pub_total_public_domestic_debt[coord]) for coord in data.DSA_PUB_TOTAL_PUBLIC_DOMESTIC_DEBT.required),
    )

@publish(data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT.schema, cells=data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT.cells)
def dsa_pub_of_which_external_debt(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_total_public_external_debt: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `dsa_pub_of_which_external_debt` using authored coordinate identities."""
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(dsa_pub_total_public_external_debt[scenario, time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100))

    return data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT.collect(evaluate(formula, data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT.required))

@publish(data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT.schema, cells=data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT.cells)
def dsa_pub_pv_of_total_public_debt(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_total_public_domestic_debt: data.Series[float | str | None], dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `dsa_pub_pv_of_total_public_debt` using authored coordinate identities."""
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'A1':
            return as_measure((0 if xl_bool(xl_lt(xl_mul(xl_div(xl_add(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100), 0)) else xl_mul(xl_div(xl_add(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100)))
        return as_measure(xl_mul(xl_div(xl_add(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100))

    return data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT.collect(evaluate(formula, data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT.required))

@publish(data.DSA_PUB_PRIMARY_DEFICIT.schema, cells=data.DSA_PUB_PRIMARY_DEFICIT.cells)
def dsa_pub_primary_deficit(*, b6_combo_non_mkt_pub_gdp_shock_label: str, input6_standard_size_threshold_option_historical_average_only: str, input6_standard_size_threshold_option_whichever_is_lower: str, dsa_pub_revenue_and_grants: data.Series[float | str | None], dsa_pub_primary_noninterest_expenditure: data.Series[float | str | None], dsa_pub_standard_test_parameter: data.Series[str | int | float | bool | None], dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter: str | int | float | bool, dsa_pub_standard_test_pb_rule: str | int | float | bool, dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule: str | int | float | bool, a1_hist_pub_historical_statistics: data.Series[float | str | None], baseline_pub_primary_deficit: data.Series[float | str | None], leftover_primary_deficit: data.Series[float | str | None], leftover_revenue_gdp: data.Series[float | str | None], b2_pb_mkt_pub_i_baseline_medium_term_projections: int | str, b2_pb_nonmkt_pub_i_baseline_medium_term_projections: int | str) -> data.Series[float | str | None]:
    """Compute `dsa_pub_primary_deficit` using authored coordinate identities."""
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B2_mkt' and time_period == 2025:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_whichever_is_lower)) else (xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_historical_average_only)) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'B2_mkt' and time_period == 2026:
            return as_measure((xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1])) if xl_bool(xl_eq(dsa_pub_primary_deficit[scenario, time_period - 1], xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1])))) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1]))))
        elif scenario == 'B6_mkt' and time_period == 2025:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_standard_test_pb_rule, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_standard_test_pb_rule, input6_standard_size_threshold_option_historical_average_only)) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'B2_nonmkt' and time_period == 2025:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter, input6_standard_size_threshold_option_historical_average_only)) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'B2_nonmkt' and time_period == 2026:
            return as_measure((xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1])) if xl_bool(xl_eq(dsa_pub_primary_deficit[scenario, time_period - 1], xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1])))) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1]))))
        elif scenario == 'B6_nonmkt' and time_period == 2025:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule, input6_standard_size_threshold_option_historical_average_only)) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b6_combo_non_mkt_pub_gdp_shock_label, leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'A1' and time_period == 2025:
            return as_measure(a1_hist_pub_historical_statistics['Primary deficit', 'Historical average'])
        elif scenario in ('B6_mkt', 'B6_nonmkt') and time_period == 2026:
            return as_measure((xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period - 1])) if xl_bool(xl_eq(dsa_pub_primary_deficit[scenario, time_period - 1], xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period - 1])))) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period - 1]))))
        elif scenario == 'A1' and time_period >= 2026:
            return as_measure(dsa_pub_primary_deficit[scenario, time_period - 1])
        return as_measure(xl_sub(dsa_pub_primary_noninterest_expenditure[scenario, time_period], dsa_pub_revenue_and_grants[scenario, time_period]))

    dsa_pub_primary_deficit = CoordinateReader('dsa_pub_primary_deficit', data.DSA_PUB_PRIMARY_DEFICIT.required, formula)
    return data.DSA_PUB_PRIMARY_DEFICIT.collect((coord, dsa_pub_primary_deficit[coord]) for coord in data.DSA_PUB_PRIMARY_DEFICIT.required)

@publish(data.DSA_PUB_REVENUE_AND_GRANTS.schema, cells=data.DSA_PUB_REVENUE_AND_GRANTS.cells)
def dsa_pub_revenue_and_grants(*, dsa_pub_of_which_grants: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], baseline_pub_revenue_grants: data.Series[float | str | None], baseline_pub_of_which_grants: data.Series[float | str | None], macro_debt_public_sector_revenues_including_grants: data.Series[float | str | None], leftover_real_interest_rate: data.Series[float | str | None], c3_commodity_pub_historical_statistics_key_variables_past_10: int | str) -> data.Series[float | str | None]:
    """Compute `dsa_pub_revenue_and_grants` using authored coordinate identities."""
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'C3' and time_period == 2028:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), xl_div(xl_mul(leftover_real_interest_rate[scenario], xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 3)), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2))))
        elif scenario == 'C3' and time_period == 2029:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), xl_div(xl_mul(leftover_real_interest_rate[scenario], xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 4)), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2))))
        elif scenario == 'C3' and time_period == 2030:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), xl_div(xl_mul(leftover_real_interest_rate[scenario], xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 5)), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2))))
        elif scenario == 'C3' and 2025 <= time_period <= 2027:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), leftover_real_interest_rate[scenario]))
        elif time_period == 2024:
            return as_measure((xl_div(xl_mul(100, macro_debt_public_sector_revenues_including_grants[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_bool(xl_isnumber(lambda: xl_div(macro_debt_public_sector_revenues_including_grants[time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period]))) else '.'))
        return as_measure(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]))

    return data.DSA_PUB_REVENUE_AND_GRANTS.collect(evaluate(formula, data.DSA_PUB_REVENUE_AND_GRANTS.required))

@publish(data.DSA_PUB_OF_WHICH_GRANTS.schema, cells=data.DSA_PUB_OF_WHICH_GRANTS.cells)
def dsa_pub_of_which_grants(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], macro_debt_public_sector_grants: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `dsa_pub_of_which_grants` using authored coordinate identities."""
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_div(macro_debt_public_sector_grants[time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100) if xl_bool(xl_isnumber(lambda: macro_debt_public_sector_grants[time_period])) else '...'))

    return data.DSA_PUB_OF_WHICH_GRANTS.collect(evaluate(formula, data.DSA_PUB_OF_WHICH_GRANTS.required))

@publish(data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE.schema, cells=data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE.cells)
def dsa_pub_primary_noninterest_expenditure(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], baseline_pub_primary_noninterest_expenditure: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `dsa_pub_primary_noninterest_expenditure` using authored coordinate identities."""
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'C3':
            return as_measure(xl_div(xl_mul(baseline_pub_primary_noninterest_expenditure[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency['B1', time_period]))
        return as_measure(xl_div(xl_mul(baseline_pub_primary_noninterest_expenditure[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE.collect(evaluate(formula, data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE.required))

@publish(data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION.schema, cells=data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION.cells)
def dsa_pub_contribution_from_real_exchange_rate_depreciation(*, dsa_pub_of_which_external_debt: data.Series[float | str | None], dsa_pub_denominator_1_g: data.Series[float | str | None], dsa_pub_average_real_interest_rate_on_external_debt_in_percent: data.Series[float | str | None], dsa_pub_real_exchange_rate_depreciation_in_percent_indicates_depreciation: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `dsa_pub_contribution_from_real_exchange_rate_depreciation` using authored coordinate identities."""
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(xl_mul(xl_div(dsa_pub_real_exchange_rate_depreciation_in_percent_indicates_depreciation[scenario, time_period], 100), dsa_pub_of_which_external_debt[scenario, time_period - 1]), xl_add(1, xl_div(dsa_pub_average_real_interest_rate_on_external_debt_in_percent[scenario, time_period], 100))), dsa_pub_denominator_1_g[scenario, time_period]))

    return data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION.collect(evaluate(formula, data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION.required))

@publish(data.DSA_PUB_DENOMINATOR_1_G.schema, cells=data.DSA_PUB_DENOMINATOR_1_G.cells)
def dsa_pub_denominator_1_g(*, dsa_pub_real_gdp_growth_in_percent: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `dsa_pub_denominator_1_g` using authored coordinate identities."""
