@publish(data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.schema, cells=data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.cells)
def dsa_pub_real_gdp_growth_in_percent(*, a1_hist_pub_historical_statistics: data.Series[float | str | None], input6_standard_size_threshold_option_historical_average_only: str, input6_standard_size_threshold_option_whichever_is_lower: str, dsa_ext_real_gdp_growth_in_percent: data.Series[float | str | None], dsa_pub_standard_test_parameter: data.Series[str | int | float | bool | None], dsa_pub_standard_test_gdp_growth_rule: str | int | float | bool, dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule: str | int | float | bool, baseline_pub_real_gdp_growth: data.Series[float | str | None], leftover_real_gdp_growth: data.Series[float | str | None], b1_gdp_pub_key_macroeconomic_fiscal_assumptions: int | str, b6_combo_mkt_pub_i_baseline_medium_term_projections: float | str, b6_combo_nonmkt_pub_i_baseline_medium_term_projections: float | str, leftover_nominal_interest_rate: float | str) -> data.Series[float | str | None]:
    """Compute `dsa_pub_real_gdp_growth_in_percent` using authored coordinate identities."""
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B1' and time_period == 2025:
            return as_measure((xl_min(xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period])), xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_whichever_is_lower)) else (xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_historical_average_only)) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period])))))
        elif scenario == 'B1' and time_period == 2026:
            return as_measure((xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period - 1])) if xl_bool(xl_eq(dsa_pub_real_gdp_growth_in_percent[scenario, time_period - 1], xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period - 1])))) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period - 1]))))
        elif scenario == 'B6_mkt' and time_period == 2025:
            return as_measure((xl_min(xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])), xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_historical_average_only)) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])))))
        elif scenario == 'B6_mkt' and time_period == 2026:
            return as_measure((xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1])) if xl_bool(xl_eq(dsa_pub_real_gdp_growth_in_percent[scenario, time_period - 1], xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1])))) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1]))))
        elif scenario == 'B6_nonmkt' and time_period == 2025:
            return as_measure((xl_min(xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])), xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_historical_average_only)) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])))))
        elif scenario == 'B6_nonmkt' and time_period == 2026:
            return as_measure((xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1])) if xl_bool(xl_eq(dsa_pub_real_gdp_growth_in_percent[scenario, time_period - 1], xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1])))) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1]))))
        elif scenario == 'C2' and time_period == 2025:
            return as_measure(xl_sub(baseline_pub_real_gdp_growth[time_period], leftover_nominal_interest_rate))
        elif scenario == 'A1' and time_period == 2025:
            return as_measure(a1_hist_pub_historical_statistics['Real GDP growth (in percent)', 'Historical average'])
        elif scenario == 'C3' and time_period <= 2030:
            return as_measure(dsa_ext_real_gdp_growth_in_percent[scenario, time_period])
        elif scenario == 'A1' and time_period >= 2026:
            return as_measure(dsa_pub_real_gdp_growth_in_percent[scenario, time_period - 1])
        return as_measure(baseline_pub_real_gdp_growth[time_period])

    dsa_pub_real_gdp_growth_in_percent = CoordinateReader('dsa_pub_real_gdp_growth_in_percent', data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.required, formula)
    return data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.collect((coord, dsa_pub_real_gdp_growth_in_percent[coord]) for coord in data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.required)

