@publish(data.DSA_PUB_DEBT_SERVICE_TO_REVENUE_AND_GRANTS_RATIO_IN_PERCENT.schema, cells=data.DSA_PUB_DEBT_SERVICE_TO_REVENUE_AND_GRANTS_RATIO_IN_PERCENT.cells)
def dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent(*, dsa_pub_revenue_and_grants: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_of_which_short_term: data.Series[float | str | None], dsa_pub_amortization_excluding_st_domestic_debt: data.Series[float | str | None], dsa_pub_interest_expenditure: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent` using authored coordinate identities."""
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'A1':
            return as_measure((0 if xl_bool(xl_lt(xl_div(xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, time_period - 1]), xl_mul(dsa_pub_revenue_and_grants[scenario, time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period])), 0)) else xl_div(xl_mul(10000, xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, time_period - 1])), xl_mul(dsa_pub_revenue_and_grants[scenario, time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period]))))
        return as_measure(xl_div(xl_mul(10000, xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, time_period - 1])), xl_mul(dsa_pub_revenue_and_grants[scenario, time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period])))

    return data.DSA_PUB_DEBT_SERVICE_TO_REVENUE_AND_GRANTS_RATIO_IN_PERCENT.collect(evaluate(formula, data.DSA_PUB_DEBT_SERVICE_TO_REVENUE_AND_GRANTS_RATIO_IN_PERCENT.required))

