@publish(data.INPUT5_PUBLIC_GFNS_3_DEBT_SERVICES_FROM_NEW_DEBT_OW_IMF.schema, cells=data.INPUT5_PUBLIC_GFNS_3_DEBT_SERVICES_FROM_NEW_DEBT_OW_IMF.cells)
def input5_public_gfns_3_debt_services_from_new_debt_ow_imf(*, input5_macro_nominal_exchange_rate_average_lcu_usd: data.Series[float | str | None], ext_debt_new_interest_external: data.Series[float | str | None], ext_debt_new_amortization_external: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `input5_public_gfns_3_debt_services_from_new_debt_ow_imf` using authored coordinate identities."""
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_add(ext_debt_new_interest_external['IMF', time_period], ext_debt_new_amortization_external['IMF', time_period]), input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]))

    return data.INPUT5_PUBLIC_GFNS_3_DEBT_SERVICES_FROM_NEW_DEBT_OW_IMF.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_3_DEBT_SERVICES_FROM_NEW_DEBT_OW_IMF.required))

