@publish(data.BLEND_PUBLISHED_TENOR_YEARS.schema, cells=data.BLEND_PUBLISHED_TENOR_YEARS.cells)
def blend_published_tenor_years(*, blend_sofr_tenor_labels: data.Series[str | None]) -> data.Series[int | str | None]:
    """Compute `blend_published_tenor_years` using authored coordinate identities."""
    data.BLEND_SOFR_TENOR_LABELS.schema.validate(blend_sofr_tenor_labels)
    def formula(tenor: str) -> int | str | None:
        if tenor in ('1 Year', '2 Year', '3 Year', '4 Year', '5 Year'):
            return as_measure(xl_numbervalue(xl_left(blend_sofr_tenor_labels[tenor], 1)), 'int')
        return as_measure(xl_numbervalue(xl_left(blend_sofr_tenor_labels[tenor], 2)), 'int')

    return data.BLEND_PUBLISHED_TENOR_YEARS.collect(evaluate(formula, data.BLEND_PUBLISHED_TENOR_YEARS.required))

