@publish(data.EXT_DEBT_NEW_INTEREST_EXTERNAL.schema, cells=data.EXT_DEBT_NEW_INTEREST_EXTERNAL.cells)
def ext_debt_new_interest_external(*, pv_base_constant_output_interest: data.Series[float | str | None], pv_base_output_interest: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `ext_debt_new_interest_external` using authored coordinate identities."""
    data.PV_BASE_CONSTANT_OUTPUT_INTEREST.schema.validate(pv_base_constant_output_interest)
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'IDA NEW Blend (also enter) -->' and time_period == 2024:
            return as_measure(xl_iferror(lambda: pv_base_constant_output_interest['IDA NEW Blend floating', time_period], lambda: 0))
        elif instrument == 'IDA NEW Blend (also enter) -->' and time_period >= 2025:
            return as_measure(xl_iferror(lambda: pv_base_output_interest['IDA NEW Blend floating', time_period], lambda: 0))
        elif instrument == 'Multilaterals':
            return as_measure(xl_sum(view(ext_debt_new_interest_external, rows=span(data.INSTRUMENT_AXIS, 'IMF', 'MULTI2'), cols=(time_period,))))
        elif instrument == 'Other Multilaterals':
            return as_measure(xl_sum(view(ext_debt_new_interest_external, rows=span(data.INSTRUMENT_AXIS, 'OTH_MULTI1', 'OTH_MULTI3'), cols=(time_period,))))
        elif instrument == 'Official Bilaterals':
            return as_measure(xl_add(ext_debt_new_interest_external['Paris Club', time_period], ext_debt_new_interest_external['Non-Paris Club', time_period]))
        elif instrument == 'Paris Club':
            return as_measure(xl_sum(view(ext_debt_new_interest_external, rows=span(data.INSTRUMENT_AXIS, 'Export Credit Agencies', 'PC5'), cols=(time_period,))))
        elif instrument == 'Non-Paris Club':
            return as_measure(xl_sum(view(ext_debt_new_interest_external, rows=span(data.INSTRUMENT_AXIS, 'Export Import Bank of NPC', 'NPC5'), cols=(time_period,))))
        elif instrument == 'Commercial':
            return as_measure(xl_sum(view(ext_debt_new_interest_external, rows=span(data.INSTRUMENT_AXIS, 'Eurobond', 'COM5'), cols=(time_period,))))
        elif instrument in ('IMF', 'IDA - regular', 'IDA - 50Y loans', 'IDA - SML', 'IDA NEW 40-year credits', 'IDA NEW Regular', 'IDA NEW 60-year credits', 'MULTI1', 'MULTI2', 'OTH_MULTI1', 'OTH_MULTI2', 'OTH_MULTI3', 'Export Credit Agencies', 'PC2', 'PC3', 'PC4', 'PC5', 'Export Import Bank of NPC', 'NPC2', 'NPC3', 'NPC4', 'NPC5', 'Eurobond', 'Commecial Bank', 'COM3', 'COM4', 'COM5') and time_period == 2024:
            return as_measure(xl_iferror(lambda: pv_base_constant_output_interest[instrument, time_period], lambda: 0))
        return as_measure(xl_iferror(lambda: pv_base_output_interest[instrument, time_period], lambda: 0))

    ext_debt_new_interest_external = CoordinateReader('ext_debt_new_interest_external', data.EXT_DEBT_NEW_INTEREST_EXTERNAL.required, formula)
    return data.EXT_DEBT_NEW_INTEREST_EXTERNAL.collect((coord, ext_debt_new_interest_external[coord]) for coord in data.EXT_DEBT_NEW_INTEREST_EXTERNAL.required)

