@publish(data.BASELINE_PUB_PUBLIC_SECTOR_DEBT.schema, cells=data.BASELINE_PUB_PUBLIC_SECTOR_DEBT.cells)
def baseline_pub_public_sector_debt(*, baseline_pub_nominal_gdp_lc: data.Series[float | str | None], macro_debt_total_public_debt_outstanding_year_end: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `baseline_pub_public_sector_debt` using authored coordinate identities."""
