@publish(data.BASELINE_PUB_PRIMARY_DEFICIT.schema, cells=data.BASELINE_PUB_PRIMARY_DEFICIT.cells)
def baseline_pub_primary_deficit(*, baseline_pub_revenue_grants: data.Series[float | str | None], baseline_pub_primary_noninterest_expenditure: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `baseline_pub_primary_deficit` using authored coordinate identities."""
    def formula(time_period: int) -> float | str | None:
        if time_period <= 2015:
            return as_measure((xl_sub(baseline_pub_primary_noninterest_expenditure[time_period], baseline_pub_revenue_grants[time_period]) if xl_bool(xl_isnumber(lambda: xl_sub(baseline_pub_primary_noninterest_expenditure[time_period], baseline_pub_revenue_grants[time_period]))) else '…'))
        return as_measure(xl_sub(baseline_pub_primary_noninterest_expenditure[time_period], baseline_pub_revenue_grants[time_period]))

    return data.BASELINE_PUB_PRIMARY_DEFICIT.collect(evaluate(formula, data.BASELINE_PUB_PRIMARY_DEFICIT.required))

@publish(data.BASELINE_PUB_PRIMARY_DEFICIT_BY_INDICATOR.schema, cells=data.BASELINE_PUB_PRIMARY_DEFICIT_BY_INDICATOR.cells)
def baseline_pub_primary_deficit_by_indicator(*, baseline_pub_primary_deficit: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `baseline_pub_primary_deficit_by_indicator` using authored coordinate identities."""
    _baseline_pub_primary_deficit_by_indicator_table_0 = view(baseline_pub_primary_deficit, cols=span(data.TIME_PERIOD_AXIS, 2014, 2023))
    def formula(variant: str) -> float | str | None:
        if variant == 'Standard':
            return as_measure(xl_stdev(_baseline_pub_primary_deficit_by_indicator_table_0))
        return as_measure(xl_average(_baseline_pub_primary_deficit_by_indicator_table_0))

    return data.BASELINE_PUB_PRIMARY_DEFICIT_BY_INDICATOR.collect(evaluate(formula, data.BASELINE_PUB_PRIMARY_DEFICIT_BY_INDICATOR.required))

@publish(data.BASELINE_PUB_REVENUE_GRANTS.schema, cells=data.BASELINE_PUB_REVENUE_GRANTS.cells)
def baseline_pub_revenue_grants(*, macro_debt_public_sector_revenues_including_grants: data.Series[float | str | None], macro_debt_gdp_current_prices_u_s_dollars: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `baseline_pub_revenue_grants` using authored coordinate identities."""
    def formula(time_period: int) -> float | str | None:
        if time_period in (2024, 2033):
            return as_measure((xl_div(xl_mul(100, macro_debt_public_sector_revenues_including_grants[time_period]), xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])) if xl_bool(xl_isnumber(lambda: xl_div(macro_debt_public_sector_revenues_including_grants[time_period], xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])))) else '...'))
        return as_measure((xl_div(xl_mul(100, macro_debt_public_sector_revenues_including_grants[time_period]), xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])) if xl_bool(xl_isnumber(lambda: xl_div(macro_debt_public_sector_revenues_including_grants[time_period], xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period])))) else '...'))

    return data.BASELINE_PUB_REVENUE_GRANTS.collect(evaluate(formula, data.BASELINE_PUB_REVENUE_GRANTS.required))

