        return as_measure(xl_add(xl_add(xl_add(xl_add(custom_pub_primary_deficit_by_year[time_period], custom_pub_interest_expenditure[time_period]), custom_pub_amortization_excluding_st_domestic_debt[time_period]), custom_pub_of_which_short_term[time_period - 1]), custom_pub_other_debt_creating_flows[time_period]))

