@publish(data.CUSTOM_PUB_PV_OF_NEW_FOREX_DEBT.schema, cells=data.CUSTOM_PUB_PV_OF_NEW_FOREX_DEBT.cells)
def custom_pub_pv_of_new_forex_debt(*, custom_pub_pv_debt: float | str, custom_pub_new_forex_borrowing_gross_usd: data.Series[float | str | None], custom_pub_total_debt_service_by_year: data.Series[float | str | None], custom_pub_amortization: data.Series[float | str | None], custom_pub_avg_nominal_interest_rate_new_borrowing_usd: float | str, custom_pub_usd_discount_rate: float | str) -> data.Series[float | str | None]:
    """Compute `custom_pub_pv_of_new_forex_debt` using authored coordinate identities."""
    def formula(time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_div(xl_mul(custom_pub_new_forex_borrowing_gross_usd[time_period], custom_pub_pv_debt), 100))
        return as_measure((xl_add(xl_sub(custom_pub_pv_of_new_forex_debt[time_period - 1], custom_pub_amortization[time_period]), custom_pub_new_forex_borrowing_gross_usd[time_period]) if xl_bool(xl_gt(custom_pub_avg_nominal_interest_rate_new_borrowing_usd, custom_pub_usd_discount_rate)) else xl_add(xl_sub(xl_mul(custom_pub_pv_of_new_forex_debt[time_period - 1], xl_add(1, custom_pub_usd_discount_rate)), custom_pub_total_debt_service_by_year[time_period]), xl_div(xl_mul(custom_pub_new_forex_borrowing_gross_usd[time_period], custom_pub_pv_debt), 100))))

    custom_pub_pv_of_new_forex_debt = CoordinateReader('custom_pub_pv_of_new_forex_debt', data.CUSTOM_PUB_PV_OF_NEW_FOREX_DEBT.required, formula)
    return data.CUSTOM_PUB_PV_OF_NEW_FOREX_DEBT.collect((coord, custom_pub_pv_of_new_forex_debt[coord]) for coord in data.CUSTOM_PUB_PV_OF_NEW_FOREX_DEBT.required)

