@dataclass(frozen=True, slots=True)
class ScanCustomPubPublicSectorDebtResult:
    """Complete named results of one recurrence group evaluation."""
    custom_pub_public_sector_debt: data.Series[float | str | None]
    custom_pub_change_in_public_sector_debt: data.Series[float | str | None]
    custom_pub_identified_debt_creating_flows: data.Series[float | str | None]
    custom_pub_automatic_debt_dynamics: data.Series[float | str | None]
    custom_pub_contribution_from_interest_rate_growth: data.Series[float | str | None]
    custom_pub_of_which_contribution_from_average_real: data.Series[float | str | None]
    custom_pub_of_which_contribution_from_real_gdp_growth: data.Series[float | str | None]
    custom_pub_average_nominal_interest_rate_domestic_debt: data.Series[float | str | None]
    custom_pub_average_real_interest_rate: data.Series[float | str | None]
    custom_pub_average_real_interest_rate_domestic_debt: data.Series[float | str | None]
    custom_pub_nominal_debt: data.Series[float | str | None]
    custom_pub_total_public_domestic_debt: data.Series[float | str | None]

def scan_custom_pub_public_sector_debt(*, custom_pub_public_sector_assets_e_g_deposits: data.Series[float | str | None], custom_pub_of_which_fx_denominated: data.Series[float | str | None], custom_pub_primary_deficit: data.Series[float | str | None], custom_pub_contribution_from_real_exchange_rate: data.Series[float | str | None], custom_pub_denominator_1_g: data.Series[float | str | None], custom_pub_other_identified_debt_creating_flows: data.Series[float | str | None], custom_pub_residual: data.Series[float | str | None], custom_pub_nominal_gdp_lc: data.Series[float | str | None], custom_pub_real_gdp_growth_by_year: data.Series[float | str | None], custom_pub_average_real_interest_rate_ext_debt: data.Series[float | str | None], custom_pub_total_public_ext_debt: data.Series[float | str | None], custom_pub_domestic_debt: data.Series[float | str | None], macro_debt_public_sector_assets_e_g_deposits: data.Series[float | str | None], macro_debt_gdp_current_prices_u_s_dollars: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], macro_debt_total_public_debt_outstanding_year_end: data.Series[float | str | None], custom_pub_inflation_rate_gdp_deflator_pct_by_year: data.Series[float | str | None], custom_pub_variables_needed_public_public_sector_assets_e_g_deposits: float | str, pv_resfin_pub_assumptions_average_interest_rate_on_domestic_debt: data.Series[float | str | None]) -> ScanCustomPubPublicSectorDebtResult:
    """Evaluate the recurrence group `custom_pub_public_sector_debt`, `custom_pub_change_in_public_sector_debt`, `custom_pub_identified_debt_creating_flows`, `custom_pub_automatic_debt_dynamics`, `custom_pub_contribution_from_interest_rate_growth`, `custom_pub_of_which_contribution_from_average_real`, `custom_pub_of_which_contribution_from_real_gdp_growth`, `custom_pub_average_nominal_interest_rate_domestic_debt`, `custom_pub_average_real_interest_rate`, `custom_pub_average_real_interest_rate_domestic_debt`, `custom_pub_nominal_debt`, `custom_pub_total_public_domestic_debt` and publish complete tensors."""
    def custom_pub_public_sector_debt_formula(time_period: int) -> float | str | None:
        if time_period == 2023:
            return as_measure((xl_div(xl_mul(100, xl_add(macro_debt_total_public_debt_outstanding_year_end[time_period], xl_sub(macro_debt_public_sector_assets_e_g_deposits[time_period], custom_pub_variables_needed_public_public_sector_assets_e_g_deposits))), xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])) if xl_bool(xl_isnumber(lambda: xl_div(macro_debt_total_public_debt_outstanding_year_end[time_period], xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])))) else '.'))
        return as_measure(xl_add(xl_add(custom_pub_public_sector_debt[time_period - 1], custom_pub_change_in_public_sector_debt[time_period]), xl_div(xl_sub(macro_debt_public_sector_assets_e_g_deposits[time_period], custom_pub_public_sector_assets_e_g_deposits[time_period]), custom_pub_nominal_gdp_lc[time_period])))

    custom_pub_public_sector_debt = CoordinateReader('custom_pub_public_sector_debt', data.CUSTOM_PUB_PUBLIC_SECTOR_DEBT.required, custom_pub_public_sector_debt_formula)
    def custom_pub_change_in_public_sector_debt_formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(custom_pub_identified_debt_creating_flows[time_period], custom_pub_residual[time_period]))

    custom_pub_change_in_public_sector_debt = CoordinateReader('custom_pub_change_in_public_sector_debt', data.CUSTOM_PUB_CHANGE_IN_PUBLIC_SECTOR_DEBT.required, custom_pub_change_in_public_sector_debt_formula)
    def custom_pub_identified_debt_creating_flows_formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(custom_pub_primary_deficit[time_period], custom_pub_automatic_debt_dynamics[time_period]), custom_pub_other_identified_debt_creating_flows[time_period]))

    custom_pub_identified_debt_creating_flows = CoordinateReader('custom_pub_identified_debt_creating_flows', data.CUSTOM_PUB_IDENTIFIED_DEBT_CREATING_FLOWS.required, custom_pub_identified_debt_creating_flows_formula)
    def custom_pub_automatic_debt_dynamics_formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(custom_pub_contribution_from_interest_rate_growth[time_period], custom_pub_contribution_from_real_exchange_rate[time_period]))

    custom_pub_automatic_debt_dynamics = CoordinateReader('custom_pub_automatic_debt_dynamics', data.CUSTOM_PUB_AUTOMATIC_DEBT_DYNAMICS.required, custom_pub_automatic_debt_dynamics_formula)
    def custom_pub_contribution_from_interest_rate_growth_formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(custom_pub_of_which_contribution_from_average_real[time_period], custom_pub_of_which_contribution_from_real_gdp_growth[time_period]))

    custom_pub_contribution_from_interest_rate_growth = CoordinateReader('custom_pub_contribution_from_interest_rate_growth', data.CUSTOM_PUB_CONTRIBUTION_FROM_INTEREST_RATE_GROWTH.required, custom_pub_contribution_from_interest_rate_growth_formula)
    def custom_pub_of_which_contribution_from_average_real_formula(time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(xl_div(custom_pub_average_real_interest_rate[time_period], 100), custom_pub_public_sector_debt[time_period - 1]), custom_pub_denominator_1_g[time_period]))

    custom_pub_of_which_contribution_from_average_real = CoordinateReader('custom_pub_of_which_contribution_from_average_real', data.CUSTOM_PUB_OF_WHICH_CONTRIBUTION_FROM_AVERAGE_REAL.required, custom_pub_of_which_contribution_from_average_real_formula)
    def custom_pub_of_which_contribution_from_real_gdp_growth_formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_neg(xl_div(custom_pub_real_gdp_growth_by_year[time_period], 100)), xl_div(custom_pub_public_sector_debt[time_period - 1], custom_pub_denominator_1_g[time_period])))

    custom_pub_of_which_contribution_from_real_gdp_growth = CoordinateReader('custom_pub_of_which_contribution_from_real_gdp_growth', data.CUSTOM_PUB_OF_WHICH_CONTRIBUTION_FROM_REAL_GDP_GROWTH.required, custom_pub_of_which_contribution_from_real_gdp_growth_formula)
    def custom_pub_average_nominal_interest_rate_domestic_debt_formula(time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure((xl_mul(None, 100) if xl_bool(xl_eq(custom_pub_total_public_domestic_debt[time_period - 1], 0)) else xl_mul(xl_div(custom_pub_domestic_debt[time_period], custom_pub_total_public_domestic_debt[time_period - 1]), 100)))
        return as_measure((xl_mul(pv_resfin_pub_assumptions_average_interest_rate_on_domestic_debt[time_period], 100) if xl_bool(xl_eq(custom_pub_total_public_domestic_debt[time_period - 1], 0)) else xl_mul(xl_div(custom_pub_domestic_debt[time_period], custom_pub_total_public_domestic_debt[time_period - 1]), 100)))

    custom_pub_average_nominal_interest_rate_domestic_debt = CoordinateReader('custom_pub_average_nominal_interest_rate_domestic_debt', data.CUSTOM_PUB_AVERAGE_NOMINAL_INTEREST_RATE_DOMESTIC_DEBT.required, custom_pub_average_nominal_interest_rate_domestic_debt_formula)
    def custom_pub_average_real_interest_rate_formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_mul(xl_div(custom_pub_of_which_fx_denominated[time_period - 1], custom_pub_public_sector_debt[time_period - 1]), custom_pub_average_real_interest_rate_ext_debt[time_period]), xl_mul(xl_sub(1, xl_div(custom_pub_of_which_fx_denominated[time_period - 1], custom_pub_public_sector_debt[time_period - 1])), custom_pub_average_real_interest_rate_domestic_debt[time_period])))

    custom_pub_average_real_interest_rate = CoordinateReader('custom_pub_average_real_interest_rate', data.CUSTOM_PUB_AVERAGE_REAL_INTEREST_RATE.required, custom_pub_average_real_interest_rate_formula)
    def custom_pub_average_real_interest_rate_domestic_debt_formula(time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_sub(custom_pub_average_nominal_interest_rate_domestic_debt[time_period], custom_pub_inflation_rate_gdp_deflator_pct_by_year[time_period]), xl_add(1, xl_div(custom_pub_inflation_rate_gdp_deflator_pct_by_year[time_period], 100))))

    custom_pub_average_real_interest_rate_domestic_debt = CoordinateReader('custom_pub_average_real_interest_rate_domestic_debt', data.CUSTOM_PUB_AVERAGE_REAL_INTEREST_RATE_DOMESTIC_DEBT.required, custom_pub_average_real_interest_rate_domestic_debt_formula)
    def custom_pub_nominal_debt_formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(custom_pub_public_sector_debt[time_period], 100), custom_pub_nominal_gdp_lc[time_period]))

    custom_pub_nominal_debt = CoordinateReader('custom_pub_nominal_debt', data.CUSTOM_PUB_NOMINAL_DEBT.required, custom_pub_nominal_debt_formula)
    def custom_pub_total_public_domestic_debt_formula(time_period: int) -> float | str | None:
        return as_measure(xl_sub(custom_pub_nominal_debt[time_period], custom_pub_total_public_ext_debt[time_period]))

    custom_pub_total_public_domestic_debt = CoordinateReader('custom_pub_total_public_domestic_debt', data.CUSTOM_PUB_TOTAL_PUBLIC_DOMESTIC_DEBT.required, custom_pub_total_public_domestic_debt_formula)
    return ScanCustomPubPublicSectorDebtResult(
        custom_pub_public_sector_debt=data.CUSTOM_PUB_PUBLIC_SECTOR_DEBT.collect((coord, custom_pub_public_sector_debt[coord]) for coord in data.CUSTOM_PUB_PUBLIC_SECTOR_DEBT.required),
        custom_pub_change_in_public_sector_debt=data.CUSTOM_PUB_CHANGE_IN_PUBLIC_SECTOR_DEBT.collect((coord, custom_pub_change_in_public_sector_debt[coord]) for coord in data.CUSTOM_PUB_CHANGE_IN_PUBLIC_SECTOR_DEBT.required),
        custom_pub_identified_debt_creating_flows=data.CUSTOM_PUB_IDENTIFIED_DEBT_CREATING_FLOWS.collect((coord, custom_pub_identified_debt_creating_flows[coord]) for coord in data.CUSTOM_PUB_IDENTIFIED_DEBT_CREATING_FLOWS.required),
        custom_pub_automatic_debt_dynamics=data.CUSTOM_PUB_AUTOMATIC_DEBT_DYNAMICS.collect((coord, custom_pub_automatic_debt_dynamics[coord]) for coord in data.CUSTOM_PUB_AUTOMATIC_DEBT_DYNAMICS.required),
        custom_pub_contribution_from_interest_rate_growth=data.CUSTOM_PUB_CONTRIBUTION_FROM_INTEREST_RATE_GROWTH.collect((coord, custom_pub_contribution_from_interest_rate_growth[coord]) for coord in data.CUSTOM_PUB_CONTRIBUTION_FROM_INTEREST_RATE_GROWTH.required),
        custom_pub_of_which_contribution_from_average_real=data.CUSTOM_PUB_OF_WHICH_CONTRIBUTION_FROM_AVERAGE_REAL.collect((coord, custom_pub_of_which_contribution_from_average_real[coord]) for coord in data.CUSTOM_PUB_OF_WHICH_CONTRIBUTION_FROM_AVERAGE_REAL.required),
        custom_pub_of_which_contribution_from_real_gdp_growth=data.CUSTOM_PUB_OF_WHICH_CONTRIBUTION_FROM_REAL_GDP_GROWTH.collect((coord, custom_pub_of_which_contribution_from_real_gdp_growth[coord]) for coord in data.CUSTOM_PUB_OF_WHICH_CONTRIBUTION_FROM_REAL_GDP_GROWTH.required),
        custom_pub_average_nominal_interest_rate_domestic_debt=data.CUSTOM_PUB_AVERAGE_NOMINAL_INTEREST_RATE_DOMESTIC_DEBT.collect((coord, custom_pub_average_nominal_interest_rate_domestic_debt[coord]) for coord in data.CUSTOM_PUB_AVERAGE_NOMINAL_INTEREST_RATE_DOMESTIC_DEBT.required),
        custom_pub_average_real_interest_rate=data.CUSTOM_PUB_AVERAGE_REAL_INTEREST_RATE.collect((coord, custom_pub_average_real_interest_rate[coord]) for coord in data.CUSTOM_PUB_AVERAGE_REAL_INTEREST_RATE.required),
        custom_pub_average_real_interest_rate_domestic_debt=data.CUSTOM_PUB_AVERAGE_REAL_INTEREST_RATE_DOMESTIC_DEBT.collect((coord, custom_pub_average_real_interest_rate_domestic_debt[coord]) for coord in data.CUSTOM_PUB_AVERAGE_REAL_INTEREST_RATE_DOMESTIC_DEBT.required),
        custom_pub_nominal_debt=data.CUSTOM_PUB_NOMINAL_DEBT.collect((coord, custom_pub_nominal_debt[coord]) for coord in data.CUSTOM_PUB_NOMINAL_DEBT.required),
        custom_pub_total_public_domestic_debt=data.CUSTOM_PUB_TOTAL_PUBLIC_DOMESTIC_DEBT.collect((coord, custom_pub_total_public_domestic_debt[coord]) for coord in data.CUSTOM_PUB_TOTAL_PUBLIC_DOMESTIC_DEBT.required),
    )

