        return as_measure(xl_add(xl_mul(xl_div(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), custom_pub_nominal_gdp_lc[time_period]), (customized_scenario_spec['size_of_shock', 2022] if xl_bool(xl_eq(custom_pub_please_do_not_change_these_numbers[time_period], customized_public_natural_disaster_year)) else 0)), 'int')

