@publish(data.CUSTOM_PUB_NOMINAL_GDP_LC.schema, cells=data.CUSTOM_PUB_NOMINAL_GDP_LC.cells)
def custom_pub_nominal_gdp_lc(*, custom_pub_real_gdp_growth_by_year: data.Series[float | str | None], macro_debt_gdp_current_prices_u_s_dollars: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], custom_pub_inflation_rate_gdp_deflator_pct_by_year: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `custom_pub_nominal_gdp_lc` using authored coordinate identities."""
    def formula(time_period: int) -> float | str | None:
        if time_period == 2023:
            return as_measure(xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))
        return as_measure(xl_mul(xl_mul(custom_pub_nominal_gdp_lc[time_period - 1], xl_add(1, xl_div(custom_pub_real_gdp_growth_by_year[time_period], 100))), xl_add(1, xl_div(custom_pub_inflation_rate_gdp_deflator_pct_by_year[time_period], 100))))

    custom_pub_nominal_gdp_lc = CoordinateReader('custom_pub_nominal_gdp_lc', data.CUSTOM_PUB_NOMINAL_GDP_LC.required, formula)
    return data.CUSTOM_PUB_NOMINAL_GDP_LC.collect((coord, custom_pub_nominal_gdp_lc[coord]) for coord in data.CUSTOM_PUB_NOMINAL_GDP_LC.required)

