        return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(custom_ext_period[time_period], customized_external_debt_profile_period), 1), custom_ext_average_interest_rate_new_debt_by_row['Average grace period on new debt'])) else (xl_div(customized_external_debt_profile_disbursement, xl_sub(custom_ext_average_interest_rate_new_debt_by_row['Average maturity of new debt'], custom_ext_average_interest_rate_new_debt_by_row['Average grace period on new debt'])) if xl_bool(xl_lt(xl_sub(xl_sub(custom_ext_period[time_period], customized_external_debt_profile_period), 1), custom_ext_average_interest_rate_new_debt_by_row['Average maturity of new debt'])) else 0)))

