    custom_ext_nominal_gdp_million_of_us_dollars_by_year = CoordinateReader('custom_ext_nominal_gdp_million_of_us_dollars_by_year', data.CUSTOM_EXT_NOMINAL_GDP_MILLION_OF_US_DOLLARS_BY_YEAR.required, formula)
    return data.CUSTOM_EXT_NOMINAL_GDP_MILLION_OF_US_DOLLARS_BY_YEAR.collect((coord, custom_ext_nominal_gdp_million_of_us_dollars_by_year[coord]) for coord in data.CUSTOM_EXT_NOMINAL_GDP_MILLION_OF_US_DOLLARS_BY_YEAR.required)

