@publish(data.IN7_RESFIN_DOMESTIC_ST.schema, cells=data.IN7_RESFIN_DOMESTIC_ST.cells)
def in7_resfin_domestic_st(*, in7_resfin_shares: data.Series[float | str | None], input7_residual_params_sparse: float | str) -> data.Series[float | str | None]:
    """Compute `in7_resfin_domestic_st` using authored coordinate identities."""
    def formula(indicator: str) -> float | str | None:
        if indicator == 'User defined':
            return as_measure(xl_sub(xl_sub(1, in7_resfin_shares['External PPG medium and long-term', indicator]), in7_resfin_shares['Domestic medium and long-term', indicator]))
        return as_measure((in7_resfin_domestic_st['User defined'] if xl_bool(xl_isnumber(lambda: in7_resfin_domestic_st['User defined'])) else input7_residual_params_sparse))

    in7_resfin_domestic_st = CoordinateReader('in7_resfin_domestic_st', data.IN7_RESFIN_DOMESTIC_ST.required, formula)
    return data.IN7_RESFIN_DOMESTIC_ST.collect((coord, in7_resfin_domestic_st[coord]) for coord in data.IN7_RESFIN_DOMESTIC_ST.required)

@publish(data.IN7_RESFIN_SHARES.schema, cells=data.IN7_RESFIN_SHARES.cells)
def in7_resfin_shares(*, ext_debt_marginal_share_domestic_mlt_residual_financing: float | str, ext_debt_marginal_share_external_ppg_mlt_residual_financing: float | str) -> data.Series[float | str | None]:
    """Compute `in7_resfin_shares` using authored coordinate identities."""
    def formula(instrument: str, variant: str) -> float | str | None:
        if instrument == 'External PPG medium and long-term' and variant == 'Default':
            return as_measure(ext_debt_marginal_share_external_ppg_mlt_residual_financing)
        elif instrument == 'Domestic medium and long-term' and variant == 'Default':
            return as_measure(ext_debt_marginal_share_domestic_mlt_residual_financing)
        return as_measure(in7_resfin_shares[instrument, 'Default'])

    in7_resfin_shares = CoordinateReader('in7_resfin_shares', data.IN7_RESFIN_SHARES.required, formula)
    return data.IN7_RESFIN_SHARES.collect((coord, in7_resfin_shares[coord]) for coord in data.IN7_RESFIN_SHARES.required)

