@publish(data.IN8_SDR_SDR_ALLOCATION_HOLDINGS_IN_MILLION_OF_USD.schema, cells=data.IN8_SDR_SDR_ALLOCATION_HOLDINGS_IN_MILLION_OF_USD.cells)
def in8_sdr_sdr_allocation_holdings_in_million_of_usd(*, input8_sdr_stock: data.Input8SdrStock) -> data.Series[int | str | None]:
    """Compute `in8_sdr_sdr_allocation_holdings_in_million_of_usd` using authored coordinate identities."""
    data.INPUT8_SDR_STOCK.schema.validate(input8_sdr_stock)
    def formula(time_period: int) -> int | str | None:
        return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(input8_sdr_stock['SDR allocation (in Million of USD)'], xl_sum(())), xl_sub(input8_sdr_stock['SDR holdings (in Million of USD)'], xl_sum(()))), 0)) else xl_sub(xl_sub(input8_sdr_stock['SDR allocation (in Million of USD)'], xl_sum(())), xl_sub(input8_sdr_stock['SDR holdings (in Million of USD)'], xl_sum(())))), 'int')

    return data.IN8_SDR_SDR_ALLOCATION_HOLDINGS_IN_MILLION_OF_USD.collect(evaluate(formula, data.IN8_SDR_SDR_ALLOCATION_HOLDINGS_IN_MILLION_OF_USD.required))

@publish(data.IN8_SDR_INTEREST_PAYMENTS_IN_MILLION_OF_USD.schema, cells=data.IN8_SDR_INTEREST_PAYMENTS_IN_MILLION_OF_USD.cells)
def in8_sdr_interest_payments_in_million_of_usd(*, input8_sdr_interest_rate: data.Input8SdrInterestRate, input8_sdr_stock: data.Input8SdrStock, in8_sdr_sdr_allocation_holdings_in_million_of_usd: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute `in8_sdr_interest_payments_in_million_of_usd` using authored coordinate identities."""
    data.INPUT8_SDR_INTEREST_RATE.schema.validate(input8_sdr_interest_rate)
    data.INPUT8_SDR_STOCK.schema.validate(input8_sdr_stock)
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure((xl_mul(xl_sub(input8_sdr_stock['SDR allocation (in Million of USD)'], input8_sdr_stock['SDR holdings (in Million of USD)']), input8_sdr_interest_rate[time_period]) if xl_bool(xl_le(input8_sdr_stock['SDR holdings (in Million of USD)'], input8_sdr_stock['SDR allocation (in Million of USD)'])) else 0), 'int')
        return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 1], input8_sdr_interest_rate[time_period]) if xl_bool(xl_le(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 1], input8_sdr_stock['SDR allocation (in Million of USD)'])) else 0), 'int')

    return data.IN8_SDR_INTEREST_PAYMENTS_IN_MILLION_OF_USD.collect(evaluate(formula, data.IN8_SDR_INTEREST_PAYMENTS_IN_MILLION_OF_USD.required))

@publish(data.IN8_SDR_PV_OF_INTEREST_PAYMENTS_IN_MILLION_OF_USD.schema, cells=data.IN8_SDR_PV_OF_INTEREST_PAYMENTS_IN_MILLION_OF_USD.cells)
def in8_sdr_pv_of_interest_payments_in_million_of_usd(*, discount_rate: float | str, in8_sdr_sdr_interest: data.Series[int | str | None], in8_sdr_of_end_2044: int | str) -> data.Series[int | str | None]:
    """Compute `in8_sdr_pv_of_interest_payments_in_million_of_usd` using authored coordinate identities."""
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(xl_npv(discount_rate, view(in8_sdr_sdr_interest, rows=(time_period,), cols=span(data.TIME_PERIOD_AXIS, time_period + 1, time_period + 5))), 'int')
        elif time_period == 2025:
            return as_measure(xl_npv(discount_rate, view(in8_sdr_sdr_interest, rows=(time_period,), cols=span(data.TIME_PERIOD_AXIS, time_period + 1, time_period + 4))), 'int')
        elif time_period == 2026:
            return as_measure(xl_npv(discount_rate, view(in8_sdr_sdr_interest, rows=(time_period,), cols=span(data.TIME_PERIOD_AXIS, time_period + 1, time_period + 3))), 'int')
        elif time_period == 2027:
            return as_measure(xl_npv(discount_rate, view(in8_sdr_sdr_interest, rows=(time_period,), cols=span(data.TIME_PERIOD_AXIS, time_period + 1, time_period + 2))), 'int')
        elif time_period == 2044:
            return as_measure(xl_npv(discount_rate, (in8_sdr_of_end_2044,)), 'int')
        return as_measure(xl_npv(discount_rate, view(in8_sdr_sdr_interest, rows=(time_period,), cols=(time_period + 1,))), 'int')

    return data.IN8_SDR_PV_OF_INTEREST_PAYMENTS_IN_MILLION_OF_USD.collect(evaluate(formula, data.IN8_SDR_PV_OF_INTEREST_PAYMENTS_IN_MILLION_OF_USD.required))

