@publish(data.CUSTOMIZED_SCENARIO_SPEC.schema, cells=data.CUSTOMIZED_SCENARIO_SPEC.cells)
def customized_scenario_spec(*, input6_tailored_params_2: data.Series[float | str | None], input6_tailored_params_3: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `customized_scenario_spec` using authored coordinate identities."""
    def formula(parameter: str, time_period: int) -> float | str | None:
        PARAMETER_TO_INPUT6_TAILORED_PARAMS_3 = {'size_of_associated_real_gdp_growth_shock': 'disaster_shock_pct_gdp', 'size_of_associated_exports_growth_shock': 'disaster_export_growth_shock'}
        if parameter == 'size_of_shock' and time_period == 2023:
            return as_measure(input6_tailored_params_2['mkt_ppg_debt_gdp_shock'])
        elif parameter in ('size_of_associated_real_gdp_growth_shock', 'size_of_associated_exports_growth_shock') and time_period == 2023:
            return as_measure(input6_tailored_params_3[PARAMETER_TO_INPUT6_TAILORED_PARAMS_3[parameter]])
        return as_measure(customized_scenario_spec[parameter, time_period + 1])

    customized_scenario_spec = CoordinateReader('customized_scenario_spec', data.CUSTOMIZED_SCENARIO_SPEC.required, formula)
    for coordinate in reversed(tuple(data.CUSTOMIZED_SCENARIO_SPEC.required)):
        customized_scenario_spec[coordinate]
    return data.CUSTOMIZED_SCENARIO_SPEC.collect((coord, customized_scenario_spec[coord]) for coord in data.CUSTOMIZED_SCENARIO_SPEC.required)

