    """Compute `custom_ext_average_interest_rate_new_debt_by_row` using authored coordinate identities."""
    def formula(indicator: str) -> float | str | None:
        if indicator == 'Average interest rate on new debt':
            return as_measure(in7_resfin_ext_mlt_effective['Avg. nominal interest rate on new borrowing in USD'])
        elif indicator == 'USD Discount rate':
            return as_measure(in7_resfin_ext_mlt_effective[indicator])
        elif indicator == 'Average grace period on new debt':
            return as_measure(in7_resfin_ext_mlt_effective['Avg. grace period'])
