@publish(key=(), domain=None, cells=data.EXTERNAL_DSA_RISK_RATING_SIGNAL_CELLS)
def external_dsa_risk_rating_signal(*, external_dsa_risk_rating_numeric: float | str, chart_numeric_risk_rating: data.Series[int | str | None], chart_numeric_risk_header: str, chart_label_risk_header: str, chart_risk_labels: data.Series[str | None]) -> str | int | float | bool:
    """Compute `external_dsa_risk_rating_signal` using authored coordinate identities."""
    data.CHART_NUMERIC_RISK_RATING.schema.validate(chart_numeric_risk_rating)
    data.CHART_RISK_LABELS.schema.validate(chart_risk_labels)
    _external_dsa_risk_rating_signal_table_0 = lazy_table(((lambda: chart_numeric_risk_header, lambda: chart_label_risk_header), (view(chart_numeric_risk_rating, rows=span(data.VARIANT_AXIS, 'Low', 'Moderate')), view(chart_risk_labels, rows=span(data.VARIANT_AXIS, 'Low', 'Moderate'))), (lambda: None, lambda: None), (lambda: None, lambda: None), (lambda: chart_numeric_risk_rating['High'], lambda: chart_risk_labels['High'])))
    try:
        return as_measure(xl_vlookup(external_dsa_risk_rating_numeric, _external_dsa_risk_rating_signal_table_0, 2, False), 'str')
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.EXTERNAL_DSA_RISK_RATING_NUMERIC_CELLS)
def external_dsa_risk_rating_numeric(*, external_baseline_breach: float | str, external_shock_breach: float | str) -> float | str:
    """Compute `external_dsa_risk_rating_numeric` using authored coordinate identities."""
    try:
        return as_measure((3 if xl_bool(xl_eq(external_baseline_breach, 1)) else (2 if xl_bool(xl_and(xl_eq(external_baseline_breach, 0), xl_eq(external_shock_breach, 1))) else 1)))
    except XlError as error:
        return error.code

