    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'IDA - regular':
            return as_measure((pv_base_discount_debt_stock[instrument, time_period] if xl_bool(xl_ge(pv_base_block_interest['IDA - regular'], pv_base_block_discount['IDA - regular'])) else xl_npv(pv_base_block_discount[instrument], view(pv_base_discount_total_debt_service, rows=(instrument,), cols=span(data.TIME_PERIOD_AXIS, time_period + 1, 2076)))))
        elif instrument == 'IDA - 50Y loans':
            return as_measure((pv_base_discount_debt_stock[instrument, time_period] if xl_bool(xl_ge(pv_base_block_interest[instrument], pv_base_block_discount[instrument])) else xl_npv(pv_base_block_discount[instrument], view(pv_base_discount_total_debt_service, rows=(instrument,), cols=span(data.TIME_PERIOD_AXIS, time_period + 1, 2074)))))
