@publish(data.PV_LC_OUTPUT_ISSUANCE_YEAR.schema, cells=data.PV_LC_OUTPUT_ISSUANCE_YEAR.cells)
def pv_lc_output_issuance_year(*, pv_lc_nr1_terms_projection_year: data.Series[int | str | None], pv_lc_terms_projection_year: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute `pv_lc_output_issuance_year` using authored coordinate identities."""
    def formula(instrument: str, holder: str, issuance_year: int) -> int | str | None:
        if instrument == 'Bonds (1 to 3 years)-LC' and issuance_year == 2024:
            return as_measure(pv_lc_nr1_terms_projection_year[instrument, holder, issuance_year], 'int')
        elif instrument in ('Bonds (4 to 7 years)-LC', 'Bonds (beyond 7 years)-LC') and issuance_year == 2024:
            return as_measure(pv_lc_terms_projection_year[instrument, holder, issuance_year], 'int')
        return as_measure(xl_add(pv_lc_output_issuance_year[instrument, holder, issuance_year - 1], 1), 'int')

    pv_lc_output_issuance_year = CoordinateReader('pv_lc_output_issuance_year', data.PV_LC_OUTPUT_ISSUANCE_YEAR.required, formula)
    return data.PV_LC_OUTPUT_ISSUANCE_YEAR.collect((coord, pv_lc_output_issuance_year[coord]) for coord in data.PV_LC_OUTPUT_ISSUANCE_YEAR.required)

@publish(data.PV_LC_OUTPUT_PERIOD_INDEX.schema, cells=data.PV_LC_OUTPUT_PERIOD_INDEX.cells)
def pv_lc_output_period_index() -> data.Series[int | str | None]:
    """Compute `pv_lc_output_period_index` using authored coordinate identities."""
    def formula(instrument: str, holder: str, issuance_year: int, time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(0, 'int')
        elif time_period == 2025:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, issuance_year, time_period - 1], 1), 'int')
        elif issuance_year == 2024 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2024, time_period - 1], 1), 'int')
        elif issuance_year == 2025 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2025, time_period - 1], 1), 'int')
        elif issuance_year == 2026 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2026, time_period - 1], 1), 'int')
        elif issuance_year == 2027 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2027, time_period - 1], 1), 'int')
        elif issuance_year == 2028 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2028, time_period - 1], 1), 'int')
        elif issuance_year == 2029 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2029, time_period - 1], 1), 'int')
        elif issuance_year == 2030 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2030, time_period - 1], 1), 'int')
        elif issuance_year == 2031 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2031, time_period - 1], 1), 'int')
        elif issuance_year == 2032 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2032, time_period - 1], 1), 'int')
        elif issuance_year == 2033 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2033, time_period - 1], 1), 'int')
        elif issuance_year == 2034 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2034, time_period - 1], 1), 'int')
        elif issuance_year == 2035 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2035, time_period - 1], 1), 'int')
        elif issuance_year == 2036 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2036, time_period - 1], 1), 'int')
        elif issuance_year == 2037 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2037, time_period - 1], 1), 'int')
        elif issuance_year == 2038 and time_period >= 2026:
            return as_measure(xl_add(pv_lc_output_period_index[instrument, holder, 2038, time_period - 1], 1), 'int')
