def pv_stress_discount_debt_stock(*, pv_stress_discount_amortization: data.Series[float | str | None], pv_stress_historical_average_disbursement: data.Series[int | str | None]) -> data.Series[float | str | None]:
    """Compute `pv_stress_discount_debt_stock` using authored coordinate identities."""
    data.PV_STRESS_HISTORICAL_AVERAGE_DISBURSEMENT.schema.validate(pv_stress_historical_average_disbursement)
    def formula(time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_sub(pv_stress_historical_average_disbursement[2024], pv_stress_discount_amortization[time_period]))
        return as_measure(xl_sub(pv_stress_discount_debt_stock[time_period - 1], pv_stress_discount_amortization[time_period]))

    pv_stress_discount_debt_stock = CoordinateReader('pv_stress_discount_debt_stock', data.PV_STRESS_DISCOUNT_DEBT_STOCK.required, formula)
    return data.PV_STRESS_DISCOUNT_DEBT_STOCK.collect((coord, pv_stress_discount_debt_stock[coord]) for coord in data.PV_STRESS_DISCOUNT_DEBT_STOCK.required)

@publish(data.PV_STRESS_DISCOUNT_AMORTIZATION.schema, cells=data.PV_STRESS_DISCOUNT_AMORTIZATION.cells)
def pv_stress_discount_amortization(*, pv_stress_calendar_period: data.Series[int | str | None], pv_stress_historical_average_disbursement: data.Series[int | str | None], pv_stress_average_maturity_of_new_debt: data.Series[float | str | None], pv_stress_average_grace_period_new_debt: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `pv_stress_discount_amortization` using authored coordinate identities."""
    data.PV_STRESS_HISTORICAL_AVERAGE_DISBURSEMENT.schema.validate(pv_stress_historical_average_disbursement)
    def formula(time_period: int) -> float | str | None:
        return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_stress_calendar_period[time_period], pv_stress_calendar_period[2024]), 1), pv_stress_average_grace_period_new_debt['Key variables at historical average'])) else (xl_div(pv_stress_historical_average_disbursement[2024], xl_sub(pv_stress_average_maturity_of_new_debt['Key variables at historical average'], pv_stress_average_grace_period_new_debt['Key variables at historical average'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_stress_calendar_period[time_period], pv_stress_calendar_period[2024]), 1), pv_stress_average_maturity_of_new_debt['Key variables at historical average'])) else 0)))

    return data.PV_STRESS_DISCOUNT_AMORTIZATION.collect(evaluate(formula, data.PV_STRESS_DISCOUNT_AMORTIZATION.required))

