@publish(data.PV_STRESS_BOUNDS_PV_OF_NEW_FOREX_DEBT_IN_USD.schema, cells=data.PV_STRESS_BOUNDS_PV_OF_NEW_FOREX_DEBT_IN_USD.cells)
def pv_stress_bounds_pv_of_new_forex_debt_in_usd(*, pv_stress_discount_pv_of_debt: data.Series[float | str | None], pv_stress_bounds_new_forex_borrowing_gross_usd: data.Series[float | str | None], pv_stress_bounds_total_debt_service_in_usd: data.Series[float | str | None], pv_stress_bounds_amortization: data.Series[float | str | None], pv_stress_average_interest_rate_new_debt: data.Series[float | str | None], pv_stress_usd_discount_rate: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `pv_stress_bounds_pv_of_new_forex_debt_in_usd` using authored coordinate identities."""
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure((pv_stress_bounds_new_forex_borrowing_gross_usd[scenario, time_period] if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_div(xl_mul(pv_stress_bounds_new_forex_borrowing_gross_usd[scenario, time_period], pv_stress_discount_pv_of_debt[time_period]), 100)))
        elif time_period == 2025:
            return as_measure((xl_add(xl_sub(pv_stress_bounds_pv_of_new_forex_debt_in_usd[scenario, time_period - 1], pv_stress_bounds_amortization[scenario, time_period]), pv_stress_bounds_new_forex_borrowing_gross_usd[scenario, time_period]) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_add(xl_sub(xl_mul(pv_stress_bounds_pv_of_new_forex_debt_in_usd[scenario, time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_bounds_total_debt_service_in_usd[scenario, time_period]), xl_div(xl_mul(pv_stress_bounds_new_forex_borrowing_gross_usd[scenario, time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Bounds Test 1: Real GDP Growth Shock' and time_period >= 2026:
            return as_measure((xl_add(xl_sub(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bounds Test 1: Real GDP Growth Shock', time_period - 1], pv_stress_bounds_amortization['Bounds Test 1: Real GDP Growth Shock', time_period]), pv_stress_bounds_new_forex_borrowing_gross_usd['Bounds Test 1: Real GDP Growth Shock', time_period]) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_add(xl_sub(xl_mul(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bounds Test 1: Real GDP Growth Shock', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_bounds_total_debt_service_in_usd['Bounds Test 1: Real GDP Growth Shock', time_period]), xl_div(xl_mul(pv_stress_bounds_new_forex_borrowing_gross_usd['Bounds Test 1: Real GDP Growth Shock', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Bound Test 2: Exports Shock' and time_period >= 2026:
            return as_measure((xl_add(xl_sub(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bound Test 2: Exports Shock', time_period - 1], pv_stress_bounds_amortization['Bound Test 2: Exports Shock', time_period]), pv_stress_bounds_new_forex_borrowing_gross_usd['Bound Test 2: Exports Shock', time_period]) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_add(xl_sub(xl_mul(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bound Test 2: Exports Shock', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_bounds_total_debt_service_in_usd['Bound Test 2: Exports Shock', time_period]), xl_div(xl_mul(pv_stress_bounds_new_forex_borrowing_gross_usd['Bound Test 2: Exports Shock', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Bound Test 4: Other Flows Shock' and time_period >= 2026:
            return as_measure((xl_add(xl_sub(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bound Test 4: Other Flows Shock', time_period - 1], pv_stress_bounds_amortization['Bound Test 4: Other Flows Shock', time_period]), pv_stress_bounds_new_forex_borrowing_gross_usd['Bound Test 4: Other Flows Shock', time_period]) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_add(xl_sub(xl_mul(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bound Test 4: Other Flows Shock', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_bounds_total_debt_service_in_usd['Bound Test 4: Other Flows Shock', time_period]), xl_div(xl_mul(pv_stress_bounds_new_forex_borrowing_gross_usd['Bound Test 4: Other Flows Shock', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Bounds Test 6: Combined Shock for Market Access Countries' and time_period >= 2026:
            return as_measure((xl_add(xl_sub(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bounds Test 6: Combined Shock for Market Access Countries', time_period - 1], pv_stress_bounds_amortization['Bounds Test 6: Combined Shock for Market Access Countries', time_period]), pv_stress_bounds_new_forex_borrowing_gross_usd['Bounds Test 6: Combined Shock for Market Access Countries', time_period]) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_add(xl_sub(xl_mul(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bounds Test 6: Combined Shock for Market Access Countries', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_bounds_total_debt_service_in_usd['Bounds Test 6: Combined Shock for Market Access Countries', time_period]), xl_div(xl_mul(pv_stress_bounds_new_forex_borrowing_gross_usd['Bounds Test 6: Combined Shock for Market Access Countries', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Bounds Test 6: Combined Shock for Non-Market Access Countries' and time_period >= 2026:
            return as_measure((xl_add(xl_sub(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period - 1], pv_stress_bounds_amortization['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period]), pv_stress_bounds_new_forex_borrowing_gross_usd['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period]) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_add(xl_sub(xl_mul(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_bounds_total_debt_service_in_usd['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period]), xl_div(xl_mul(pv_stress_bounds_new_forex_borrowing_gross_usd['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        return as_measure((xl_add(xl_sub(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bounds Test 5: Exchange Rate Shock', time_period - 1], pv_stress_bounds_amortization['Bounds Test 5: Exchange Rate Shock', time_period]), pv_stress_bounds_new_forex_borrowing_gross_usd['Bounds Test 5: Exchange Rate Shock', time_period]) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_add(xl_sub(xl_mul(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bounds Test 5: Exchange Rate Shock', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_bounds_total_debt_service_in_usd['Bounds Test 5: Exchange Rate Shock', time_period]), xl_div(xl_mul(pv_stress_bounds_new_forex_borrowing_gross_usd['Bounds Test 5: Exchange Rate Shock', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))

    pv_stress_bounds_pv_of_new_forex_debt_in_usd = CoordinateReader('pv_stress_bounds_pv_of_new_forex_debt_in_usd', data.PV_STRESS_BOUNDS_PV_OF_NEW_FOREX_DEBT_IN_USD.required, formula)
    return data.PV_STRESS_BOUNDS_PV_OF_NEW_FOREX_DEBT_IN_USD.collect((coord, pv_stress_bounds_pv_of_new_forex_debt_in_usd[coord]) for coord in data.PV_STRESS_BOUNDS_PV_OF_NEW_FOREX_DEBT_IN_USD.required)

@publish(data.PV_STRESS_BOUNDS_TOTAL_DEBT_SERVICE_IN_USD.schema, cells=data.PV_STRESS_BOUNDS_TOTAL_DEBT_SERVICE_IN_USD.cells)
def pv_stress_bounds_total_debt_service_in_usd(*, pv_stress_opening_stock_percent_of_face: int | str, pv_stress_bounds_interest: data.Series[float | str | None], pv_stress_bounds_amortization: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `pv_stress_bounds_total_debt_service_in_usd` using authored coordinate identities."""
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Bound Test 2: Exports Shock' and time_period == 2024:
            return as_measure(xl_add(pv_stress_opening_stock_percent_of_face, pv_stress_bounds_amortization['Bound Test 2: Exports Shock', time_period]))
        elif scenario == 'Bounds Test 1: Real GDP Growth Shock' and time_period >= 2025:
            return as_measure(xl_add(pv_stress_bounds_interest['Bounds Test 1: Real GDP Growth Shock', time_period], pv_stress_bounds_amortization['Bounds Test 1: Real GDP Growth Shock', time_period]))
        elif scenario == 'Bound Test 2: Exports Shock' and time_period >= 2025:
            return as_measure(xl_add(pv_stress_bounds_interest['Bound Test 2: Exports Shock', time_period], pv_stress_bounds_amortization['Bound Test 2: Exports Shock', time_period]))
        elif scenario == 'Bound Test 4: Other Flows Shock' and time_period >= 2025:
            return as_measure(xl_add(pv_stress_bounds_interest['Bound Test 4: Other Flows Shock', time_period], pv_stress_bounds_amortization['Bound Test 4: Other Flows Shock', time_period]))
        elif scenario == 'Bounds Test 6: Combined Shock for Market Access Countries' and time_period >= 2025:
            return as_measure(xl_add(pv_stress_bounds_interest['Bounds Test 6: Combined Shock for Market Access Countries', time_period], pv_stress_bounds_amortization['Bounds Test 6: Combined Shock for Market Access Countries', time_period]))
        elif scenario == 'Bounds Test 6: Combined Shock for Non-Market Access Countries' and time_period >= 2025:
            return as_measure(xl_add(pv_stress_bounds_interest['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period], pv_stress_bounds_amortization['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period]))
        return as_measure(xl_add(pv_stress_bounds_interest['Bounds Test 5: Exchange Rate Shock', time_period], pv_stress_bounds_amortization['Bounds Test 5: Exchange Rate Shock', time_period]))

    return data.PV_STRESS_BOUNDS_TOTAL_DEBT_SERVICE_IN_USD.collect(evaluate(formula, data.PV_STRESS_BOUNDS_TOTAL_DEBT_SERVICE_IN_USD.required))

