    """Compute `pv_resfin_pub_discount_amortization` using authored coordinate identities."""
    def formula(instrument: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_resfin_pub_opening_stock_period, pv_resfin_pub_opening_stock_period), 1), pv_resfin_pub_assumptions_avg_grace_period['External MLT debt'])) else (xl_div(pv_resfin_pub_opening_stock_disbursement, xl_sub(pv_resfin_pub_assumptions_avg_maturity_incl_grace_period['External MLT debt'], pv_resfin_pub_assumptions_avg_grace_period['External MLT debt'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_resfin_pub_opening_stock_period, pv_resfin_pub_opening_stock_period), 1), pv_resfin_pub_assumptions_avg_maturity_incl_grace_period['External MLT debt'])) else 0)))
        return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_resfin_pub_discount_period['External MLT debt', time_period], pv_resfin_pub_opening_stock_period), 1), pv_resfin_pub_assumptions_avg_grace_period['External MLT debt'])) else (xl_div(pv_resfin_pub_opening_stock_disbursement, xl_sub(pv_resfin_pub_assumptions_avg_maturity_incl_grace_period['External MLT debt'], pv_resfin_pub_assumptions_avg_grace_period['External MLT debt'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_resfin_pub_discount_period['External MLT debt', time_period], pv_resfin_pub_opening_stock_period), 1), pv_resfin_pub_assumptions_avg_maturity_incl_grace_period['External MLT debt'])) else 0)))

    return data.PV_RESFIN_PUB_DISCOUNT_AMORTIZATION.collect(evaluate(formula, data.PV_RESFIN_PUB_DISCOUNT_AMORTIZATION.required))

